  "settings.clearLibraryV2Hint": "Tyhjentää hakemiston (kappaleet, albumit, artistit). Sen mukana menetetään: soittolistojen sisältö, arviot, kirjanmerkit, suosikit, käsin kootut kokoelmaboksit ja albumien muokkaukset. Yhtään musiikkitiedostoa ei poisteta. Tietokannasta tehdään varmuuskopio juuri ennen. Skannaus palauttaa vain kappaleet. Kirjaston päivittämiseen käytä sen sijaan täyttä skannausta: se säilyttää kokoelmaboksit ja albumien muokkaukset.",
