  "renderer.wav24Hint": "Lähetä aitoa 24-bittistä WAVia. Tarjotaan oletuksena; estetään vain, kun hakutesti osoittaa, ettei tämä toistin ilmoita tukevansa audio/L24- eikä audio/wav-muotoa.",
  "renderer.depthCapNotRate": "Huomaa: bittisyvyyden rajoittaminen ei rajoita näytetaajuutta. 96 kHz/24-bittisestä tiedostosta tulee 96 kHz/16-bittinen — edelleen 96 kHz. Jos toistimesi enimmäistaajuus on 48 kHz, aseta myös ”Enimmäistaajuus”.",
  "renderer.flacAndWavSplitBySource": "”Pakota WAV” koskee vain muita kuin FLAC-lähteitä (ALAC, AAC…) — se kiertää toistimen ALAC-dekooderin. FLAC-tiedostosi lähetetään edelleen natiivina FLACina.",
  "renderer.wav24Unproven": "Yksikään hakutesti ei ole vielä onnistunut: 24-bittinen pysyy tarjolla, mutta mikään ei vahvista, että tämä laite osaa lukea sitä. Paina yllä ”Tarkista”.",
  "renderer.wav24Refused": "Hakutesti vastasi: tämä laite ei ilmoita tukevansa audio/L24- eikä audio/wav-muotoa. 24-bittinen pysyy suljettuna — sen lähettäminen tuottaisi hiljaisuutta.",
  "renderer.startDelay": "Käynnistysviive",
