  "renderer.fluxContinu": "Jatkuva virta kappaleiden välillä",
  "renderer.fluxContinuHint": "Soittimille, jotka yhdistävät kaksi peräkkäistä kappaletta huonosti: samaa formaattia olevat peräkkäiset kappaleet lähetetään yhtenä WAV-virtana ilman käsittelyä. Ensimmäisessä formaatin vaihdossa palataan tavalliseen kappaleittaiseen toistoon.",
