  "settings.dlnaCap16bitHint": "Ota käyttöön, jos hi-res (24-bittinen) on mykkä tällä toistimella mutta 16-bittinen toimii (Ruark R3). Muuntaa 16-bittiseksi FLACiksi sen sijaan, että lähettäisi suoraan 24-bittistä, jota toistin ei osaa purkaa.",
  "settings.alacPassthroughHint": "Lähetä ALAC sellaisenaan tälle toistimelle (bit-perfect, ei FLAC-transkoodausta). Ota käyttöön vain, jos toistin purkaa ALACin natiivisti, muuten ääntä ei kuulu.",
  "settings.aacPassthroughHint": "Lähetä AAC sellaisenaan tälle toistimelle sen sijaan, että se transkoodattaisiin FLACiksi. Lähde on jo häviöllisesti pakattu, joten transkoodaus ei paranna laatua — se vain viivästyttää ensimmäistä ääntä. Ota käyttöön vain, jos toistin purkaa AACin natiivisti, muuten ääntä ei kuulu.",
