  "settings.signOutConfirm": "Kirjaudutaanko ulos Mozaiklabs-tililtä? Tämä palvelin irrotetaan tilistä: sen verkossa oleva kirjastokopio ja Tune Circle -jakonsa poistetaan, ja tilin tuomat Premium-ominaisuudet lakkaavat (lisenssiavain pysyy voimassa). Voit kirjautua myöhemmin uudelleen.",
