  "settings.telemetryHint": "Lähetä käyttötilastoja Tunen parantamiseksi: instanssin tunniste, versio, alusta, kirjaston koot, yhdistetyt palvelut ja laitemallit.",
  "settings.telemetryOffScope": "Sen poistaminen käytöstä lopettaa myös yhteisön metatietojen jakamisen ja lataamisen. Lisenssin vahvistus jatkuu, joten Premium ei koskaan katoa.",
  "settings.communitySync": "Yhteisön metatietojen jakaminen",
  "settings.communitySyncHint": "Osallistu yhteisön täydennykseen: MusicBrainz-tunnistukset, tyylilajit ja tekijätiedot (säveltäjä, kapellimestari, esittäjät) jaetaan Tune-palvelimien kesken. Anonyymi — ei koskaan tiedostojasi.",
  "settings.cloudListens": "Lähetä kuunteluni tililleni",
  "settings.cloudListensHint": "Lisää tämän palvelimen kuuntelut tilisi ”Kuunteluni”-sivulle muiden Tune-palvelimiesi kuuntelujen kanssa. Kustakin kuuntelusta lähetetään: päivämäärä, kesto, läpinäkymätön profiilitunniste, nimi, artisti, albumi sekä, jos tiedossa, ISRC ja MusicBrainz-tunnus. Ei koskaan tiedostopolkujasi, IP-osoitettasi eikä vyöhykkeidesi nimiä. Oletuksena pois.",
  "settings.cloudListensLink": "Näytä kuunteluni sivustolla mozaiklabs.fr",
