  "settings.cloudListensConsentBenefit": "Mitä saat: ”Kuunteluni”-sivun, joka kokoaa kaikkien Tune-palvelimiesi kuuntelut, sekä yhteisön kuuntelut.",
  "settings.cloudListensConsentSettingsReminder": "Voit muuttaa mielesi milloin tahansa kohdassa Asetukset › Järjestelmä.",
