  "settings.communityShare": "Jaa arvioni ja kuunteluni yhteisön kanssa (anonyymisti)",
  "settings.communityShareHint": "Erillinen ”Kuunteluni”-sivusta ja oletuksena pois. Albumiarviosi (ilman kommenttia) ja tilillesi käyttöönoton JÄLKEEN tulevat kuuntelut lasketaan julkisiin, anonyymeihin kokonaismääriin, jotka näytetään albumin sivulla, kun mukana on vähintään kolme eri henkilöä. Yksittäisiä tietoja ei koskaan näytetä. Pois kytkeminen poistaa osuutesi välittömästi.",
  "settings.communityMeasuresReceive": "Vastaanota analyysituloksia yhteisöltä",
  "settings.communityMeasuresReceiveHint": "Oletuksena pois. FLAC-tiedostoillesi palvelin pyytää mozaiklabs.fr-sivustolta ReplayGain-arvot, dynamiikka-alueet ja akustiset tunnisteet, jotka vähintään kaksi muuta asennusta on jo mitannut täsmälleen samasta signaalista. Ne täydentävät vain puuttuvat tiedot: tagejasi ja omia mittauksiasi ei koskaan korvata. Sivusto saa vain lyhyen etuliitteen, ei koskaan tiedostoluetteloasi.",
