  "settings.communityMeasuresContributeHint": "Oletuksena pois. Palvelin lähettää sivustolle vain mittaukset, jotka se on itse tehnyt FLAC-tiedostoistasi (ReplayGain, dynamiikka-alue, akustinen tunniste), tunnistettuina niiden signaalin allekirjoituksella. Polkuja, nimiä, tiedostonimiä tai tilejä ei lähetetä: palvelin tunnistautuu asennusnumerollaan. Pois kytkeminen poistaa lähetetyt tiedot.",
